import pandas as pd
import numpy as np
import torch
import torch.nn as nn
import argparse
import warnings
import glob
from pathlib import Path
from typing import Dict, List, Tuple, Optional, Union
from utils.preprocessing import preprocessing 

# Silence UserWarnings often generated by pandas/torch
warnings.filterwarnings("ignore", category=UserWarning)


# --- Configuration & Paths ---

BASE_DIR = Path('/kyb/agpd/wwang/data/')
OUT_DIR = Path('/kyb/agpd/wwang/sst-pomdp/outputs/')

# Inputs
ENC_PATH = OUT_DIR / "encoder.pt"
DATA_DIR = BASE_DIR / "sst_valid_raw" 
VALID_FILES_LIST = BASE_DIR / "sst_valid_filenames.txt"
META_CSV = OUT_DIR / "stats_beh_full.csv"

# Output
OUTPUT_EMBEDDINGS_CSV = OUT_DIR / "embeddings.csv"

# Model Constants (Needed for loading the state dict)
RESULT_LEVELS = ["GS", "GE", "GM", "SS", "SE"]
MODEL_DIM = 64
OUT_DIM = 32


# --- Model Definitions (Copied for standalone execution) ---
# NOTE: These must match the definitions in pipeline_transformer_snpe.py

class SinusoidalPE(nn.Module):
    def __init__(self, d_model: int, max_len: int = 1024):
        super().__init__()
        pe = torch.zeros(max_len, d_model)
        pos = torch.arange(0, max_len).unsqueeze(1).float()
        div = torch.exp(torch.arange(0, d_model, 2).float() * (-np.log(10000.0) / d_model))
        pe[:, 0::2] = torch.sin(pos * div)
        pe[:, 1::2] = torch.cos(pos * div)
        self.register_buffer("pe", pe)

    def forward(self, x):
        N = x.size(1)
        return x + self.pe[:N].unsqueeze(0)


class TrialTransformer(nn.Module):
    def __init__(self, in_dim: int, model_dim: int = 64, nhead: int = 4, nlayers: int = 2,
                 dropout: float = 0.1, out_dim: int = 32, use_pos_enc: bool = True):
        super().__init__()
        self.proj = nn.Linear(in_dim, model_dim)
        self.use_pos = use_pos_enc
        if use_pos_enc:
            self.pe = SinusoidalPE(model_dim)
        
        encoder_layer = nn.TransformerEncoderLayer(
            d_model=model_dim, nhead=nhead, dim_feedforward=model_dim*4,
            dropout=dropout, batch_first=True
        )
        self.encoder = nn.TransformerEncoder(encoder_layer, num_layers=nlayers)
        self.head = nn.Sequential(
            nn.LayerNorm(model_dim),
            nn.Linear(model_dim, out_dim)
        )

    def forward(self, x):
        h = self.proj(x)
        if self.use_pos:
            h = self.pe(h)
        h = self.encoder(h)
        # 1. Subject Embedding (mean-pooled)
        z = h.mean(dim=1) 
        # 2. Trial Latents (h before pooling, used for std calculation)
        return self.head(z), h # Return both the final embedding and the trial latents

# --- Feature Builder (Copied from pipeline) ---

def build_per_trial_features(df: pd.DataFrame, use_index=True) -> np.ndarray:
    """Constructs per-trial feature vectors (N_trials x Features)."""
    N = len(df)
    idx_map = {k: i for i, k in enumerate(RESULT_LEVELS)}

    oh = np.zeros((N, len(RESULT_LEVELS)), dtype=np.float32)
    res = df["result"].astype(str).values
    for t, r in enumerate(res):
        if r in idx_map: oh[t, idx_map[r]] = 1.0

    rt = pd.to_numeric(df["rt"], errors="coerce").values.astype(np.float32)
    ssd = pd.to_numeric(df["ssd"], errors="coerce").values.astype(np.float32)
    
    rt_nan = np.isnan(rt).astype(np.float32)
    ssd_nan = np.isnan(ssd).astype(np.float32)
    rt = np.nan_to_num(rt, nan=0.0)
    ssd = np.nan_to_num(ssd, nan=0.0)

    # Lag-1 features
    prev_oh = np.roll(oh, 1, axis=0); prev_oh[0, :] = 0.0
    prev_rt = np.roll(rt, 1); prev_rt[0] = 0.0
    prev_ssd = np.roll(ssd, 1); prev_ssd[0] = 0.0
    delta_ssd = ssd - prev_ssd

    cols = [oh, rt[:, None], ssd[:, None], rt_nan[:, None], ssd_nan[:, None],
            prev_oh, prev_rt[:, None], prev_ssd[:, None], delta_ssd[:, None]]
    
    if use_index:
        t_idx = np.linspace(-1.0, 1.0, N, dtype=np.float32)[:, None]
        cols.append(t_idx)

    return np.concatenate(cols, axis=1).astype(np.float32)


# --- Core Logic Functions ---

def load_encoder(path: Path, in_dim: int):
    """Initializes and loads the trained Transformer encoder."""
    if not path.exists():
        raise FileNotFoundError(f"Trained encoder file not found at: {path}")

    # Use a dummy input dim to initialize, then check the loaded state_dict
    encoder = TrialTransformer(in_dim=in_dim, model_dim=MODEL_DIM, out_dim=OUT_DIM)
    encoder.load_state_dict(torch.load(path))
    encoder.eval()
    for p in encoder.parameters(): p.requires_grad = False
    return encoder


def process_subjects(
    encoder: nn.Module, 
    files_list_path: Path, 
    data_dir: Path, 
    meta_csv_path: Path
) -> pd.DataFrame:
    """
    Iterates through subject files, computes embeddings, and saves the results.
    """
    if not files_list_path.exists():
        raise FileNotFoundError(f"File list not found: {files_list_path}")
        
    # Load list of valid filenames
    with files_list_path.open('r') as f:
        filenames = [line.strip() for line in f if line.strip()]

    # Load metadata for subject_id/year lookups (optional, but good for robust output)
    df_meta = pd.read_csv(meta_csv_path)
    
    results = []
    count_ok = 0
    count_err = 0
    
    print(f"Starting embedding generation for {len(filenames)} subjects...")

    for fname in filenames:
        file_path = data_dir / fname
        if not file_path.exists():
            continue

        try:
            # 1. Load & Preprocess Data
            df_obs = preprocessing(str(file_path))
            X_trial_features = build_per_trial_features(df_obs)
            
            # 2. Encode
            X_tensor = torch.tensor(X_trial_features[None, ...], dtype=torch.float32)
            
            with torch.no_grad():
                # z_emb is the final mean-pooled embedding, h_latents are the trial latents
                z_emb, h_latents = encoder(X_tensor) 

            z_vec = z_emb.squeeze(0).numpy()
            
            # Calculate std dev of trial latents (before the final head)
            h_std_vec = h_latents.std(dim=1).squeeze().numpy() 

            # 3. Prepare Output Row
            meta_row = df_meta[df_meta["filename"] == fname].iloc[0]
            sid = meta_row.get("subject_id", file_path.stem)
            year = meta_row.get("year", "baseline")

            row = {
                "subject_id": sid,
                "year": year,
                "filename": fname,
                # Scalar summaries
                "embedding_vec_mean": float(np.mean(z_vec)),
                "embedding_vec_std": float(np.std(z_vec)),
                "trial_latents_mean_std": float(np.mean(h_std_vec)) 
            }
            
            # Save full embedding vector elements (emb_0, emb_1, ...)
            for i, val in enumerate(z_vec):
                row[f"emb_{i}"] = val
            
            results.append(row)
            count_ok += 1
            
            if count_ok % 100 == 0:
                print(f"Processed {count_ok} files...")

        except Exception as e:
            print(f"[Error] {fname}: {e}")
            count_err += 1

    print(f"Done. Stats: OK={count_ok}, Errors={count_err}")
    return pd.DataFrame(results)


# --- Main Execution ---

def main():
    parser = argparse.ArgumentParser(description="Generate embeddings from trained Transformer.")
    # Use default paths from CONFIG, allow override via CLI
    parser.add_argument("--encoder_path", type=Path, default=ENC_PATH, help="Path to the trained encoder.pt file.")
    parser.add_argument("--files_list", type=Path, default=VALID_FILES_LIST, help="Path to the list of valid filenames.")
    parser.add_argument("--data_dir", type=Path, default=DATA_DIR, help="Directory containing the subject raw data zips.")
    parser.add_argument("--meta_csv", type=Path, default=META_CSV, help="CSV containing subject_id and year metadata.")
    parser.add_argument("--out", type=Path, default=OUTPUT_EMBEDDINGS_CSV, help="Output path for the embeddings CSV.")
    
    args = parser.parse_args()

    try:
        # Determine the input dimension dynamically from a dummy run
        # NOTE: This ensures consistency with build_per_trial_features logic
        temp_file = next(args.data_dir.glob("NDAR_*.csv.zip"))
        df_dummy = preprocessing(str(temp_file))
        in_dim = build_per_trial_features(df_dummy).shape[1]
        print(f"Inferred Transformer input dimension: {in_dim}")

        # 1. Load Encoder
        encoder = load_encoder(args.encoder_path, in_dim)

        # 2. Process Subjects
        df_embeddings = process_subjects(
            encoder, args.files_list, args.data_dir, args.meta_csv
        )

        # 3. Save Output
        args.out.parent.mkdir(parents=True, exist_ok=True)
        df_embeddings.to_csv(args.out, index=False)
        print(f"Successfully saved embeddings for {len(df_embeddings)} subjects to {args.out}")

    except Exception as e:
        print(f"A critical error occurred: {e}")

if __name__ == "__main__":
    main()